record.field:
import json
import logging

_logger = logging.getLogger('remotecontrol_pesyr')

Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
today_str = fields.Date.today()

condition = [
    ('remotecontrol_params', '!=', False),
    ('device_id.remotecontrol_id', '=', Remote.id),
]
if selected_device_ids:
    condition.append(('device_id', 'in', selected_device_ids))
sensors = Sensor.search(condition)
_logger.info(
    '[PESYR] Plan build start: remote_id=%s selected_device_ids=%s sensors=%s',
    Remote.id,
    selected_device_ids,
    len(sensors),
)

sensor_ids = [s.id for s in sensors]
last_readings_map = {}
if sensors:
    cr = env.cr
    cr.execute(
        'SELECT DISTINCT ON (sensor_id) sensor_id, measurement_time '
        'FROM mdm_measurement_device_sensor_reading '
        'WHERE sensor_id IN %s AND active = TRUE '
        'ORDER BY sensor_id, measurement_time DESC',
        (tuple(sensor_ids),)
    )
    for sid, mtime in cr.fetchall():
        last_readings_map[sid] = mtime
    _logger.info(
        '[PESYR] Last readings fetched for %s sensors',
        len(last_readings_map),
    )

plan = []
plan_skipped_missing_device_id = 0
plan_skipped_invalid_sensor_id = 0
plan_skipped_sensor_id_out_of_range = 0
plan_details = []
for sensor in sensors:
    device = sensor.device_id
    try:
        scfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        _logger.warning(
            '[PESYR] Invalid sensor remotecontrol_params: sensor_id=%s',
            sensor.id,
        )
        scfg = {}
    try:
        dcfg = json.loads(device.remotecontrol_params or '{}') or {}
    except Exception:
        _logger.warning(
            '[PESYR] Invalid device remotecontrol_params: device_id=%s',
            device.id,
        )
        dcfg = {}

    descriptor = dcfg.get('device_id') or ''
    if not descriptor:
        plan_skipped_missing_device_id += 1
        _logger.info(
            '[PESYR] Sensor skipped (missing device_id): sensor_id=%s device_id=%s',
            sensor.id,
            device.id,
        )
        if len(plan_details) < 30:
            plan_details.append({
                'sensor_id': sensor.id,
                'device_id': device.id,
                'status': 'skipped',
                'reason': 'missing_device_id',
            })
        continue
    contador_id = scfg.get('sensor_id')

    try:
        contador_id = int(contador_id)
    except Exception:
        plan_skipped_invalid_sensor_id += 1
        _logger.info(
            '[PESYR] Sensor skipped (invalid sensor_id): sensor_id=%s device_id=%s value=%s',
            sensor.id,
            device.id,
            contador_id,
        )
        if len(plan_details) < 30:
            plan_details.append({
                'sensor_id': sensor.id,
                'device_id': device.id,
                'status': 'skipped',
                'reason': 'invalid_sensor_id',
                'value': contador_id,
            })
        continue

    if 0 <= contador_id <= 5:
        value_field = 'cont%s' % (contador_id + 1)
    elif 1 <= contador_id <= 6:
        value_field = 'cont%s' % contador_id
    else:
        plan_skipped_sensor_id_out_of_range += 1
        _logger.info(
            '[PESYR] Sensor skipped (sensor_id out of range): sensor_id=%s device_id=%s sensor_cfg_id=%s',
            sensor.id,
            device.id,
            contador_id,
        )
        if len(plan_details) < 30:
            plan_details.append({
                'sensor_id': sensor.id,
                'device_id': device.id,
                'status': 'skipped',
                'reason': 'sensor_id_out_of_range',
                'sensor_cfg_id': contador_id,
            })
        continue

    start_cfg = dcfg.get('start_date')
    last_m = last_readings_map.get(sensor.id)
    if last_m:
        try:
            initial_date = fields.Date.to_string(
                fields.Datetime.from_string(last_m)
            )
        except Exception:
            initial_date = str(last_m)[:10]
    elif start_cfg:
        initial_date = start_cfg[:10]
    else:
        year_str = today_str[:4]
        initial_date = '%s-01-01' % year_str

    plan.append({
        'sensor_id': sensor.id,
        'device_id': device.id,
        'descriptor': descriptor,
        'contador_id': contador_id,
        'value_field': value_field,
        'initial_date': initial_date,
    })
    if len(plan_details) < 30:
        plan_details.append({
            'sensor_id': sensor.id,
            'device_id': device.id,
            'descriptor': descriptor,
            'contador_id': contador_id,
            'value_field': value_field,
            'initial_date': initial_date,
            'status': 'planned',
        })

bag['sensors_plan'] = plan
bag['plan_count'] = len(plan)
bag['pesyr_plan_summary'] = {
    'executed_at': fields.Datetime.now(),
    'selected_device_ids': selected_device_ids,
    'sensors_found': len(sensors),
    'plan_count': len(plan),
    'skipped_missing_device_id': plan_skipped_missing_device_id,
    'skipped_invalid_sensor_id': plan_skipped_invalid_sensor_id,
    'skipped_sensor_id_out_of_range': plan_skipped_sensor_id_out_of_range,
}
bag['pesyr_plan_details'] = plan_details
try:
    bag['pesyr_plan_json'] = json.dumps(plan, ensure_ascii=True, indent=2)
except Exception as json_error:
    bag['pesyr_plan_json_error'] = str(json_error)
_logger.info(
    '[PESYR] Plan build done: remote_id=%s plan_count=%s',
    Remote.id,
    len(plan),
)
Remote.message_post(
    body='[PESYR] Plan: sensors=%s planned=%s skipped=%s' % (
        len(sensors),
        len(plan),
        len(sensors) - len(plan),
    )
)
